// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint96 amount) public {
        vm.assume(amount > 0);
        uint256 fund = uint256(amount) + 1;
        vm.deal(address(c), fund);

        // adversarial counterparty: a receiver that refuses payment
        Reverter r = new Reverter();

        uint256 before = address(c).balance;
        // owner is the test contract (deployer in setUp)
        bool ok;
        try c.sendTo(address(r), uint256(amount)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: if sendTo reports success, the contract's balance MUST have
        // dropped by exactly the amount sent (funds actually left), otherwise
        // the call must have reverted.
        assertTrue(!ok || (address(c).balance == before - uint256(amount)));
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
